def inline(s):
 s=html.escape(s)
 s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
 s=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s)
 s=re.sub(r'(https?://[^\s<>]+)',lambda m:'<a href="'+m[1].rstrip('.,;')+'">'+m[1].rstrip('.,;')+'</a>'+m[1][len(m[1].rstrip('.,;')):],s)
 return s
def markdown(s):
 lines=s.splitlines();out=[];i=0
 while i<len(lines):
  line=lines[i]
  if not line.strip() or line.startswith('<!--'):i+=1;continue
  if line.startswith('```'):
   block=[];i+=1
   while i<len(lines) and not lines[i].startswith('```'):block.append(lines[i]);i+=1
   out.append('<pre><code>'+html.escape('\n'.join(block))+'</code></pre>');i+=1;continue
  if line.startswith('#'):
   m=re.match(r'^(#{1,6}) (.*)',line)
   if m:
    level=len(m[1]);anchor='kap-'+str(len(out));out.append(f'<h{level} id="{anchor}">'+inline(m[2])+f'</h{level}>');i+=1;continue
  if line.startswith('|'):
   rows=[]
   while i<len(lines) and lines[i].startswith('|'):
    vals=[x.strip() for x in lines[i].strip('|').split('|')]
    if not all(re.fullmatch(r'[-: ]+',x) for x in vals):rows.append(vals)
    i+=1
   out.append('<div class="tablewrap"><table>'+''.join('<tr>'+''.join(('<th>' if j==0 else '<td>')+inline(c)+('</th>' if j==0 else '</td>') for c in row)+'</tr>' for j,row in enumerate(rows))+'</table></div>');continue
  if line.startswith('>'):
   block=[]
   while i<len(lines) and lines[i].startswith('>'):block.append(lines[i].lstrip('> ').strip());i+=1
   out.append('<blockquote>'+'<br>'.join(inline(x) for x in block)+'</blockquote>');continue
  if line.startswith('- ') or re.match(r'^\d+\. ',line):
   ordered=not line.startswith('- ');tag='ol' if ordered else 'ul';items=[]
   while i<len(lines) and ((lines[i].startswith('- ') and not ordered) or (re.match(r'^\d+\. ',lines[i]) and ordered)):
    items.append('<li>'+inline(re.sub(r'^(?:- |\d+\. )','',lines[i]))+'</li>');i+=1
   out.append('<'+tag+'>'+''.join(items)+'</'+tag+'>');continue
  block=[line];i+=1
  while i<len(lines) and lines[i].strip() and not lines[i].startswith(('#','- ','|','>','```','<!--')) and not re.match(r'^\d+\. ',lines[i]):block.append(lines[i]);i+=1
  out.append('<p>'+inline(' '.join(block))+'</p>')
 return '\n'.join(out)
